using System.Collections.Generic;

public static class Analytics
{
    // Sum of the squares of the even numbers.
    public static int SumEvenSquares(List<int> nums)
    {
        int total = 0;
        foreach (var n in nums)
        {
            if (n % 2 == 0)
            {
                total += n * n;
            }
        }
        return total;
    }
}

