using System.Collections.Generic;
using Xunit;

public class AnalyticsTests
{
    [Fact]
    public void SumsSquaresOfEvens()
    {
        // evens 2,4,6 -> 4 + 16 + 36 = 56
        Assert.Equal(56, Analytics.SumEvenSquares(new List<int> { 1, 2, 3, 4, 6 }));
    }

    [Fact]
    public void EmptyIsZero()
    {
        Assert.Equal(0, Analytics.SumEvenSquares(new List<int>()));
    }

    [Fact]
    public void NoEvensIsZero()
    {
        Assert.Equal(0, Analytics.SumEvenSquares(new List<int> { 1, 3, 5 }));
    }
}

